1657	/// Make every staged publish visible. The full intent — merged
1658	/// packument bytes plus the staged tmp-file locations — is sealed into
1659	/// the commit journal first, so a crash or I/O failure mid-apply can
1660	/// never leave the batch partially published: startup recovery rolls
1661	/// a sealed transaction forward. If sealing itself fails, nothing was
1662	/// promoted and the staged tmp files are cleaned up here.
1663	///
1664	/// Within each package, tarballs are promoted before the packument so
1665	/// a successful packument write never advertises a tarball that's
1666	/// missing from disk.
1667	async fn commit_publishes(
1668	    state: &AppState,
1669	    staged: Vec<StagedPublish>,
1670	) -> Result<(), RegistryError> {
1671	    let journal = state.inner.storage.publish_journal();
1672	    let entries: Vec<JournaledPublish<'_>> = staged
1673	        .iter()
1674	        .map(|stage| JournaledPublish {
1675	            name: &stage.name,
1676	            packument: &stage.merged_bytes,
1677	            slots: &stage.slots,
1678	        })
1679	        .collect();
1680	    let sealed = journal.seal(&entries).await;
1681	    drop(entries);
1682	    let txn = match sealed {
1683	        Ok(txn) => txn,
1684	        Err(err) => {
1685	            for stage in staged {
1686	                cleanup_tmp_slots(stage.slots).await;
1687	            }
1688	            return Err(err);
1689	        }
1690	    };
1691	    // Past the seal the transaction is committed: the apply below is pure
1692	    // roll-forward, and failures must NOT clean up the staged files. If
1693	    // the apply fails partway, complete it immediately via the same
1694	    // idempotent recovery path so a running server never leaves the batch
1695	    // partially visible; startup recovery is the final backstop if even
1696	    // that fails.
1697	    let apply_result = async {
1698	        for stage in staged {
1699	            for slot in stage.slots {
1700	                state.inner.storage.finalize_tarball_slot(slot).await?;
1701	            }
1702	            state.inner.storage.write_hosted_packument(&stage.name, &stage.merged_bytes).await?;
1703	        }
1704	        Ok::<(), RegistryError>(())
1705	    }
1706	    .await;
1707	    match apply_result {
1708	        Ok(()) => {
1709	            txn.finish().await;
1710	            Ok(())
1711	        }
1712	        Err(apply_err) => {
1713	            tracing::warn!(error = %apply_err, "publish apply failed after seal; rolling forward");
1714	            txn.roll_forward(&state.inner.storage).await.map_err(|_| apply_err)
1715	        }
1716	    }
1717	}
