1719	fn publish_created_response() -> Response {
1720	    let body = json!({ "ok": true, "success": true });
1721	    let bytes = serde_json::to_vec(&body).expect("static-shape JSON serializes");
1722	    Response::builder()
1723	        .status(StatusCode::CREATED)
1724	        .header(header::CONTENT_TYPE, "application/json")
1725	        .body(Body::from(bytes))
1726	        .expect("static-shape response always builds")
1727	}
