1729	/// Remove every tmp tarball file that a partially-completed publish
1730	/// already wrote. Errors are swallowed: the caller is already
1731	/// returning an error response, and a leftover `*.tmp.*` file is
1732	/// harmless beyond a small amount of disk.
1733	async fn cleanup_tmp_slots(slots: Vec<crate::storage::TarballSlot>) {
1734	    for slot in slots {
1735	        let _ = tokio::fs::remove_file(&slot.tmp_path).await;
1736	    }
1737	}
